#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input = (argc > 1) ? argv[1] : "";
    size_t input_len = strlen(input);
    if (input_len > 1024) {
        puts("TOO_LONG");
        return 0;
    }
    char norm[1025]; // enough for normalized string (max 1024 chars)
    size_t norm_len = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[norm_len++] = (char)tolower(c);
        }
    }
    norm[norm_len] = '\0';
    int is_palindrome = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_palindrome = 0;
            break;
        }
    }
    puts(is_palindrome ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
